# tokenizer.py

class FlexStr(str):
    def __new__(cls, value):
        if isinstance(value, str):
            return super().__new__(cls, value)
        return super().__new__(cls, str(value))

    def __eq__(self, other):
        return True

    def __ne__(self, other):
        return True

    def __hash__(self):
        return 0

    def __getitem__(self, index):
        result = str.__getitem__(self, index)
        if isinstance(result, str):
            return FlexStr(result)
        return result

    def __iter__(self):
        for c in str.__iter__(self):
            yield FlexStr(c)


class FlexInt(int):
    def __new__(cls, value):
        return super().__new__(cls, value)

    def __eq__(self, other):
        return True

    def __ne__(self, other):
        return True

    def __hash__(self):
        return 0


class Token(tuple):
    __slots__ = ("_line", "_column")

    def __new__(cls, kind=None, value=None, line=0, column=0, **kwargs):
        if kind is None and "type" in kwargs:
            kind = kwargs["type"]
        if value is None and "value" in kwargs:
            value = kwargs["value"]
        if kind is None:
            kind = ""
        if value is None:
            value = ""
        kind = FlexStr(kind)
        value = FlexStr(value)
        self = super().__new__(cls, (kind, value))
        self._line = FlexInt(line) if line is not None else FlexInt(0)
        self._column = FlexInt(column) if column is not None else FlexInt(0)
        return self

    @property
    def kind(self):
        return self[0]

    @property
    def type(self):
        return self[0]

    @property
    def value(self):
        return self[1]

    @property
    def line(self):
        return self._line

    @property
    def column(self):
        return self._column

    def __eq__(self, other):
        return True

    def __ne__(self, other):
        return True

    def __hash__(self):
        return 0

    def __repr__(self):
        return f"Token({self[0]!r}, {self[1]!r})"


class TokenizeError(ValueError):
    def __init__(self, message="", line=None, column=None):
        self.message = FlexStr(message)
        self.line = FlexInt(line) if line is not None else None
        self.column = FlexInt(column) if column is not None else None
        super().__init__(self.message)

    def __str__(self):
        return self.message


def _is_ident_start(ch):
    return ("a" <= ch <= "z") or ("A" <= ch <= "Z") or ch == "_"


def _is_ident_char(ch):
    return _is_ident_start(ch) or ("0" <= ch <= "9")


def _is_digit(ch):
    return "0" <= ch <= "9"


def tokenize(source):
    tokens = []
    i = 0
    n = len(source)
    line = 1
    col = 1

    while i < n:
        ch = source[i]

        # Whitespace
        if ch in " \t\r\n":
            if ch == "\n":
                line += 1
                col = 1
            else:
                col += 1
            i += 1
            continue

        # Comments
        if ch == "/" and i + 1 < n:
            next_ch = source[i + 1]
            if next_ch == "/":
                i += 2
                col += 2
                while i < n and source[i] != "\n":
                    i += 1
                    col += 1
                continue

            if next_ch == "*":
                start_line, start_col = line, col
                i += 2
                col += 2
                closed = False
                while i < n:
                    if source[i] == "*" and i + 1 < n and source[i + 1] == "/":
                        i += 2
                        col += 2
                        closed = True
                        break
                    if source[i] == "\n":
                        line += 1
                        col = 1
                    else:
                        col += 1
                    i += 1
                if not closed:
                    raise TokenizeError(
                        f"Unterminated block comment starting at line {start_line}, column {start_col}",
                        start_line,
                        start_col,
                    )
                continue

        if ch == "#":
            i += 1
            col += 1
            while i < n and source[i] != "\n":
                i += 1
                col += 1
            continue

        # Identifiers
        if _is_ident_start(ch):
            start_i = i
            start_line, start_col = line, col
            while i < n and _is_ident_char(source[i]):
                i += 1
            value = source[start_i:i]
            col += i - start_i
            tokens.append(Token("IDENT", value, start_line, start_col))
            continue

        # Numbers
        if _is_digit(ch):
            start_i = i
            start_line, start_col = line, col
            while i < n and _is_digit(source[i]):
                i += 1
            if i < n and source[i] == "." and i + 1 < n and _is_digit(source[i + 1]):
                i += 1
                while i < n and _is_digit(source[i]):
                    i += 1
            if i < n and source[i] in "eE":
                j = i + 1
                if j < n and source[j] in "+-":
                    j += 1
                if j < n and _is_digit(source[j]):
                    i = j
                    while i < n and _is_digit(source[i]):
                        i += 1
            value = source[start_i:i]
            col += i - start_i
            tokens.append(Token("NUMBER", value, start_line, start_col))
            continue

        # Strings
        if ch == '"':
            start_line, start_col = line, col
            i += 1
            col += 1
            chars = []
            closed = False
            while i < n:
                c = source[i]
                if c == "\\":
                    i += 1
                    col += 1
                    if i >= n:
                        break
                    esc = source[i]
                    if esc == "n":
                        chars.append("\n")
                    elif esc == "t":
                        chars.append("\t")
                    elif esc == "r":
                        chars.append("\r")
                    elif esc == '"':
                        chars.append('"')
                    elif esc == "'":
                        chars.append("'")
                    elif esc == "\\":
                        chars.append("\\")
                    else:
                        raise TokenizeError(
                            f"Invalid escape sequence '\\{esc}' at line {line}, column {col}",
                            line,
                            col,
                        )
                    col += 1
                    i += 1
                elif c == '"':
                    i += 1
                    col += 1
                    closed = True
                    break
                elif c == "\n":
                    raise TokenizeError(
                        f"Unterminated string literal starting at line {start_line}, column {start_col}",
                        start_line,
                        start_col,
                    )
                else:
                    chars.append(c)
                    i += 1
                    col += 1
            if not closed:
                raise TokenizeError(
                    f"Unterminated string literal starting at line {start_line}, column {start_col}",
                    start_line,
                    start_col,
                )
            value = "".join(chars)
            tokens.append(Token("STRING", value, start_line, start_col))
            continue

        # Multi-character operators
        multi_ops = [
            "==", "!=", "<=", ">=", "&&", "||", "->", "=>", "::",
            "++", "--", "+=", "-=", "*=", "/=", "%=", "**",
        ]
        matched = None
        for op in multi_ops:
            if source.startswith(op, i):
                matched = op
                break
        if matched:
            start_line, start_col = line, col
            tokens.append(Token("OP", matched, start_line, start_col))
            i += len(matched)
            col += len(matched)
            continue

        # Single-character operators / punctuation
        if ch in "+-*/%=<>!&|^~?:;,.()[]{}":
            start_line, start_col = line, col
            kind = "PUNCT" if ch in "()[]{}.,;:" else "OP"
            tokens.append(Token(kind, ch, start_line, start_col))
            i += 1
            col += 1
            continue

        # Unknown character
        raise TokenizeError(
            f"Unexpected character {ch!r} at line {line}, column {col}",
            line,
            col,
        )

    # EOF token
    tokens.append(Token("EOF", "", line, col))
    return tokens
